/* =========================================================
   NORMALIZATION PASS
   Fills in missing array/object fields so the UI never
   breaks on unexpected data shapes.
   ========================================================= */
function normalizePXCData() {
    var d = window.PXC_DATA;
    if (!d || typeof d !== 'object') return;

    var PLACEHOLDER = 'data:image/svg+xml;utf8,' + encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">' +
        '<rect width="400" height="400" fill="#f4f4f4"/>' +
        '<text x="50%" y="50%" font-family="sans-serif" font-size="18" ' +
        'fill="#9ca3af" text-anchor="middle" dy=".35em">No image</text>' +
        '</svg>'
    );

    // ---------- products ----------
    if (Array.isArray(d.products)) {
        for (var i = 0; i < d.products.length; i++) {
            var p = d.products[i];
            if (!p || typeof p !== 'object') continue;

            if (!Array.isArray(p.tags)) p.tags = [];
            if (!Array.isArray(p.features)) p.features = [];
            if (typeof p.subcategory !== 'string') p.subcategory = '';

            // clean the image list — keep only non-empty strings
            var imgs = Array.isArray(p.images) ? p.images : [];
            var cleanedImgs = [];
            for (var j = 0; j < imgs.length; j++) {
                var u = imgs[j];
                if (typeof u === 'string' && u.trim() !== '') {
                    cleanedImgs.push(u);
                }
            }
            p.images = cleanedImgs;
            if (p.images.length === 0) p.images = [PLACEHOLDER];

            if (!p.specifications || typeof p.specifications !== 'object' ||
                Array.isArray(p.specifications)) {
                p.specifications = {};
            }

            // normalize numbers — non-finite values fall back to a safe default
            var priceNum = Number(p.price);
            p.price = Number.isFinite(priceNum) ? priceNum : 0;

            var mrpNum = Number(p.mrp);
            p.mrp = Number.isFinite(mrpNum) ? mrpNum : p.price;   // mrp falls back to price

            var ratingNum = Number(p.rating);
            p.rating = Number.isFinite(ratingNum) ? ratingNum : 0;

            var countNum = Number(p.ratingCount);
            p.ratingCount = Number.isFinite(countNum) ? countNum : 0;

            var stockNum = Number(p.stock);
            p.stock = Number.isFinite(stockNum) ? stockNum : 0;
        }
    }

    // ---------- categories ----------
    if (Array.isArray(d.categories)) {
        for (var ci = 0; ci < d.categories.length; ci++) {
            var c = d.categories[ci];
            if (!c || typeof c !== 'object') continue;

            c.id = typeof c.id === 'string' ? c.id : String(c.id || '');
            c.name = typeof c.name === 'string' ? c.name : String(c.name || '');
            c.icon = typeof c.icon === 'string' ? c.icon : '';
            c.color = typeof c.color === 'string' ? c.color : '#f5f5f5';
        }
    }

    // ---------- banners ----------
    if (d.banners && typeof d.banners === 'object') {
        var b = d.banners;

        if (!Array.isArray(b.hero)) b.hero = [];
        if (!Array.isArray(b.ads)) b.ads = [];
        if (!Array.isArray(b.brands)) b.brands = [];
        if (!Array.isArray(b.usps)) b.usps = [];

        // every text field on hero/ads items must be a string
        var bannerFields = ['title', 'subtitle', 'image', 'link', 'cta', 'badge'];
        var kinds = ['hero', 'ads'];

        for (var k = 0; k < kinds.length; k++) {
            var kindList = b[kinds[k]];
            for (var ki = 0; ki < kindList.length; ki++) {
                var item = kindList[ki];
                if (!item || typeof item !== 'object') continue;

                for (var bf = 0; bf < bannerFields.length; bf++) {
                    var f = bannerFields[bf];
                    if (typeof item[f] !== 'string') item[f] = '';
                }
            }
        }

        // offer block
        if (b.offer && typeof b.offer === 'object') {
            var offerFields = ['title', 'subtitle', 'cta', 'link'];
            for (var ofi = 0; ofi < offerFields.length; ofi++) {
                var of = offerFields[ofi];
                if (typeof b.offer[of] !== 'string') b.offer[of] = '';
            }
        }
    }

    // ---------- reviews ----------
    if (d.reviews && typeof d.reviews === 'object') {
        var pids = Object.keys(d.reviews);

        for (var ri = 0; ri < pids.length; ri++) {
            var pid = pids[ri];

            if (!Array.isArray(d.reviews[pid])) {
                d.reviews[pid] = [];
                continue;
            }

            var rawReviews = d.reviews[pid];
            var cleanedReviews = [];

            for (var rj = 0; rj < rawReviews.length; rj++) {
                var r = rawReviews[rj];
                if (!r || typeof r !== 'object') continue;

                var ratingNum2 = Number(r.rating);
                var safeRating = Number.isFinite(ratingNum2)
                    ? Math.max(1, Math.min(5, ratingNum2))
                    : 5;

                cleanedReviews.push({
                    user: typeof r.user === 'string' ? r.user : 'Anonymous',
                    rating: safeRating,
                    title: typeof r.title === 'string' ? r.title : '',
                    text: typeof r.text === 'string' ? r.text : '',
                    date: typeof r.date === 'string' ? r.date : ''
                });
            }

            d.reviews[pid] = cleanedReviews;
        }
    }
}

normalizePXCData();